twin.source:
// Digital twin for Sense.I.6P6 — TDK InvenSense ICM-42686P, a 6-axis IMU
// (3-axis accel + 3-axis gyro + temperature) with FIFO, Wake-on-Motion, and
// APEX tilt/tap/pedometer, exposing two interrupt pins (INT1, INT2).
//
// Model: the physical world (orientation/acceleration in mg, rotation rate in
// dps, die temperature in °C) is driven by the controls. Host calls convert
// that world into raw register values using the EXACT integer conversions from
// the driver (drivers/tile_sense_i_6p6.c), so firmware reading the tile gets
// the same numbers it would from real hardware. The INT pins assert when a
// routed condition (data-ready / FIFO watermark / WOM / tilt) is true.
//
// A few config fields (WOM enable + threshold, INT routing, tilt enable) are
// surfaced as controls too, so the behavior of the output pins can be exercised
// here without a firmware program. In real use, firmware sets these via the
// set_*/int*/wom_* host calls, which write the very same state fields.
import type { TileSim } from '../tileSim';

interface State {
  // ── physical stimulus (the world the IMU senses) ──
  ax_mg: number;
  ay_mg: number;
  az_mg: number;
  gx_dps: number;
  gy_dps: number;
  gz_dps: number;
  temp_c: number;

  // ── configuration (driver init defaults: ±8g, ±1000dps, 100Hz, low-noise) ──
  accel_range: number; // 0:±32g 1:±16g 2:±8g 3:±4g 4:±2g
  gyro_range: number; // 0:±4000 1:±2000 2:±1000 3:±500 4:±250 5:±125 6:±62.5 7:±31.25 dps
  odr_code: number; // ODR enum (display only)
  accel_pm: number; // 0:off 2:low-power 3:low-noise
  gyro_pm: number; // 0:off 1:standby 3:low-noise
  temp_enabled: number;

  // ── interrupt routing + electrical config ──
  int1_drdy: number;
  int1_fifo: number;
  int1_wom: number;
  int2_drdy: number;
  int2_fifo: number;
  int2_wom: number;
  int_active_high: number; // 1 = active-high (default), 0 = active-low
  int_latched: number;

  // ── wake-on-motion ──
  wom_enabled: number;
  wom_thr_mg: number;

  // ── APEX (DMP) features ──
  tilt_enabled: number;
  ped_enabled: number;
  tap_enabled: number;
  step_count: number;
  step_cadence: number; // u6.2 fixed point (÷4 → steps/s)

  // ── FIFO ──
  fifo_mode: number; // 0:bypass 1:stream 2:stop-on-full
  fifo_watermark: number;
  fifo_count: number;
  fifo_lost: number;

  // Open index signature (satisfies TileSim's SimState) — also holds a few
  // write-only config scratch fields the driver has but the model doesn't read.
  [field: string]: number;
}

const WHO_AM_I = 0x44;
const I2C_ADDR_DEFAULT = 0x69;

// ── exact conversions from the driver ────────────────────────────────────────

// accel_lsb_per_g(): ±32g→1024 … ±2g→16384
const ACCEL_LSB_PER_G = [1024, 2048, 4096, 8192, 16384];
function accelLsbPerG(range: number): number {
  return ACCEL_LSB_PER_G[Math.max(0, Math.min(4, range | 0))];
}
// gyro LSB/dps table, ±4000dps→8.2 … ±31.25dps→1048.6
const GYRO_LSB_PER_DPS = [8.2, 16.4, 32.8, 65.5, 131.0, 262.0, 524.3, 1048.6];
function gyroLsbPerDps(range: number): number {
  return GYRO_LSB_PER_DPS[Math.max(0, Math.min(7, range | 0))];
}

function clampI16(v: number): number {
  const r = Math.round(v);
  return r > 32767 ? 32767 : r < -32768 ? -32768 : r;
}
const rawAccel = (mg: number, range: number) => clampI16((mg / 1000) * accelLsbPerG(range));
const rawGyro = (dps: number, range: number) => clampI16(dps * gyroLsbPerDps(range));
// get_temperature returns the raw int16; degC = raw/132.48 + 25.0
const rawTemp = (c: number) => clampI16((c - 25.0) * 132.48);

// ── derived physical quantities ──────────────────────────────────────────────

const accelMagMg = (s: State) => Math.hypot(s.ax_mg, s.ay_mg, s.az_mg);
// Sensors powered (low-power or low-noise) ⇒ data is being produced.
const sensorsOn = (s: State) => s.accel_pm >= 2 || s.gyro_pm >= 3;
// WOM is high-passed acceleration: deviation of |a| from 1g, vs threshold.
const motionMg = (s: State) => Math.abs(accelMagMg(s) - 1000);
const womActive = (s: State) => s.wom_enabled === 1 && motionMg(s) > s.wom_thr_mg;
// Tilt-detect: angle of the device from its face-up reference (+Z), in degrees.
function tiltFromVerticalDeg(s: State): number {
  const mag = accelMagMg(s) || 1;
  const c = Math.max(-1, Math.min(1, s.az_mg / mag));
  return (Math.acos(c) * 180) / Math.PI;
}
const tiltActive = (s: State) => s.tilt_enabled === 1 && tiltFromVerticalDeg(s) > 35;
const dataReady = (s: State) => (sensorsOn(s) ? 1 : 0);
const fifoThsActive = (s: State) => s.fifo_mode !== 0 && s.fifo_count >= s.fifo_watermark;

// Inclination of one axis from horizontal, in centi-degrees (driver helper).
function tiltAxisCentiDeg(s: State, axis: number): number {
  const a = [s.ax_mg, s.ay_mg, s.az_mg];
  const target = a[axis % 3];
  const o0 = a[(axis + 1) % 3];
  const o1 = a[(axis + 2) % 3];
  const perp = Math.hypot(o0, o1);
  return Math.round((Math.atan2(target, perp) * 18000) / Math.PI);
}

// INT status byte (clear-on-read register, modeled as the live condition).
function intStatus(s: State): number {
  return (dataReady(s) ? 0x08 : 0) | (fifoThsActive(s) ? 0x04 : 0);
}

// arg-or-current helper for setters (called with [] in the read-out → harmless
// idempotent re-apply; called with a value by firmware → applies it).
const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;

const sim: TileSim<State> = {
  tile: 'Sense.I.6P6',

  defaultState: {
    ax_mg: 0,
    ay_mg: 0,
    az_mg: 1000, // resting flat, face-up: 1g on +Z
    gx_dps: 0,
    gy_dps: 0,
    gz_dps: 0,
    temp_c: 25,

    accel_range: 2, // ±8g
    gyro_range: 2, // ±1000 dps
    odr_code: 6, // 100 Hz
    accel_pm: 3, // low-noise
    gyro_pm: 3, // low-noise
    temp_enabled: 1,

    int1_drdy: 0,
    int1_fifo: 0,
    int1_wom: 0,
    int2_drdy: 0,
    int2_fifo: 0,
    int2_wom: 0,
    int_active_high: 1,
    int_latched: 0,

    wom_enabled: 0,
    wom_thr_mg: 200,

    tilt_enabled: 0,
    ped_enabled: 0,
    tap_enabled: 0,
    step_count: 0,
    step_cadence: 0,

    fifo_mode: 0,
    fifo_watermark: 1,
    fifo_count: 0,
    fifo_lost: 0,
  },

  controls: [
    // physical stimulus
    {
      type: 'slider',
      field: 'ax_mg',
      label: 'Accel X',
      min: -2000,
      max: 2000,
      step: 10,
      unit: 'mg',
    },
    {
      type: 'slider',
      field: 'ay_mg',
      label: 'Accel Y',
      min: -2000,
      max: 2000,
      step: 10,
      unit: 'mg',
    },
    {
      type: 'slider',
      field: 'az_mg',
      label: 'Accel Z',
      min: -2000,
      max: 2000,
      step: 10,
      unit: 'mg',
    },
    {
      type: 'slider',
      field: 'gx_dps',
      label: 'Gyro X',
      min: -2000,
      max: 2000,
      step: 5,
      unit: 'dps',
    },
    {
      type: 'slider',
      field: 'gy_dps',
      label: 'Gyro Y',
      min: -2000,
      max: 2000,
      step: 5,
      unit: 'dps',
    },
    {
      type: 'slider',
      field: 'gz_dps',
      label: 'Gyro Z',
      min: -2000,
      max: 2000,
      step: 5,
      unit: 'dps',
    },
    {
      type: 'slider',
      field: 'temp_c',
      label: 'Temperature',
      min: -40,
      max: 85,
      step: 1,
      unit: '°C',
    },
    // config knobs (firmware sets these via host calls; exposed here to exercise outputs)
    { type: 'slider', field: 'wom_enabled', label: 'WOM enable', min: 0, max: 1, step: 1 },
    {
      type: 'slider',
      field: 'wom_thr_mg',
      label: 'WOM threshold',
      min: 0,
      max: 1000,
      step: 5,
      unit: 'mg',
    },
    { type: 'slider', field: 'int1_wom', label: 'Route WOM→INT1', min: 0, max: 1, step: 1 },
    { type: 'slider', field: 'int1_drdy', label: 'Route DRDY→INT1', min: 0, max: 1, step: 1 },
    {
      type: 'slider',
      field: 'tilt_enabled',
      label: 'Tilt detect (→INT1)',
      min: 0,
      max: 1,
      step: 1,
    },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_sense_i_6p6_find: () => ({ scalar: I2C_ADDR_DEFAULT }),
    tile_sense_i_6p6_init: () => ({
      scalar: 0,
      nextState: { accel_range: 2, gyro_range: 2, odr_code: 6, accel_pm: 3, gyro_pm: 3 },
    }),
    tile_sense_i_6p6_sleep: () => ({ nextState: { accel_pm: 0, gyro_pm: 0 } }),
    tile_sense_i_6p6_wake: () => ({ nextState: { accel_pm: 3, gyro_pm: 3 } }),
    tile_sense_i_6p6_reset: () => ({ scalar: 0 }),
    tile_sense_i_6p6_subsystem_reset: () => ({ nextState: { fifo_count: 0 } }),
    tile_sense_i_6p6_process: ({ state }) => ({ scalar: intStatus(state) }),
    tile_sense_i_6p6_on_event: () => ({ nextState: {} }),

    // ── configuration ──
    tile_sense_i_6p6_set_accel_range: ({ state, args }) => ({
      nextState: { accel_range: pick(args, 0, state.accel_range) },
    }),
    tile_sense_i_6p6_set_gyro_range: ({ state, args }) => ({
      nextState: { gyro_range: pick(args, 0, state.gyro_range) },
    }),
    tile_sense_i_6p6_set_accel_odr: ({ state, args }) => ({
      nextState: { odr_code: pick(args, 0, state.odr_code) },
    }),
    tile_sense_i_6p6_set_gyro_odr: ({ state, args }) => ({
      nextState: { odr_code: pick(args, 0, state.odr_code) },
    }),
    tile_sense_i_6p6_set_power_mode: ({ state, args }) => ({
      nextState: { accel_pm: pick(args, 0, state.accel_pm), gyro_pm: pick(args, 1, state.gyro_pm) },
    }),
    tile_sense_i_6p6_set_filter_bw: ({ args }) => ({ nextState: { _filter_bw: pick(args, 0, 0) } }),
    tile_sense_i_6p6_set_filter_order: ({ args }) => ({
      nextState: { _filter_order: pick(args, 0, 0) },
    }),
    tile_sense_i_6p6_set_temp_filter: ({ args }) => ({
      nextState: { _temp_filter: pick(args, 0, 0) },
    }),
    tile_sense_i_6p6_set_temp_enabled: ({ state, args }) => ({
      nextState: { temp_enabled: pick(args, 0, state.temp_enabled) },
    }),

    // ── data reads (raw register values, exactly as firmware would get) ──
    tile_sense_i_6p6_data_ready: ({ state }) => ({ scalar: dataReady(state) }),
    tile_sense_i_6p6_get_raw_accels: ({ state }) => ({
      array: [
        rawAccel(state.ax_mg, state.accel_range),
        rawAccel(state.ay_mg, state.accel_range),
        rawAccel(state.az_mg, state.accel_range),
      ],
    }),
    tile_sense_i_6p6_get_raw_gyros: ({ state }) => ({
      array: [
        rawGyro(state.gx_dps, state.gyro_range),
        rawGyro(state.gy_dps, state.gyro_range),
        rawGyro(state.gz_dps, state.gyro_range),
      ],
    }),
    tile_sense_i_6p6_get_raw_6dof: ({ state }) => ({
      array: [
        rawAccel(state.ax_mg, state.accel_range),
        rawAccel(state.ay_mg, state.accel_range),
        rawAccel(state.az_mg, state.accel_range),
        rawGyro(state.gx_dps, state.gyro_range),
        rawGyro(state.gy_dps, state.gyro_range),
        rawGyro(state.gz_dps, state.gyro_range),
      ],
    }),
    tile_sense_i_6p6_get_temperature: ({ state }) => ({ scalar: rawTemp(state.temp_c) }),
    tile_sense_i_6p6_get_raw_all: ({ state }) => ({
      array: [
        rawTemp(state.temp_c),
        rawAccel(state.ax_mg, state.accel_range),
        rawAccel(state.ay_mg, state.accel_range),
        rawAccel(state.az_mg, state.accel_range),
        rawGyro(state.gx_dps, state.gyro_range),
        rawGyro(state.gy_dps, state.gyro_range),
        rawGyro(state.gz_dps, state.gyro_range),
      ],
    }),

    // ── orientation / motion helpers (driver integer math) ──
    tile_sense_i_6p6_is_face_up: ({ state }) => ({
      scalar:
        Math.abs(state.az_mg - 1000) <= 200 &&
        Math.abs(state.ax_mg) <= 300 &&
        Math.abs(state.ay_mg) <= 300
          ? 1
          : 0,
    }),
    tile_sense_i_6p6_is_face_down: ({ state }) => ({
      scalar:
        Math.abs(state.az_mg + 1000) <= 200 &&
        Math.abs(state.ax_mg) <= 300 &&
        Math.abs(state.ay_mg) <= 300
          ? 1
          : 0,
    }),
    tile_sense_i_6p6_is_moving: ({ state, args }) => ({
      scalar: motionMg(state) > pick(args, 0, 50) ? 1 : 0,
    }),
    tile_sense_i_6p6_read_tilt_centi_degrees: ({ state, args }) => ({
      scalar: tiltAxisCentiDeg(state, pick(args, 0, 2)),
    }),
    tile_sense_i_6p6_wait_for_tap: ({ state }) => ({ scalar: state.tap_enabled }),
    tile_sense_i_6p6_wait_for_motion: ({ state }) => ({ scalar: motionMg(state) > 50 ? 1 : 0 }),

    // ── interrupts ──
    tile_sense_i_6p6_int1_config: ({ state, args }) => ({
      nextState: {
        int_active_high: args.length ? (args[0] & 0x01 ? 1 : 0) : state.int_active_high,
        int_latched: args.length ? (args[0] & 0x04 ? 1 : 0) : state.int_latched,
      },
    }),
    tile_sense_i_6p6_int2_config: ({ state, args }) => ({
      nextState: {
        int_active_high: args.length ? (args[0] & 0x01 ? 1 : 0) : state.int_active_high,
        int_latched: args.length ? (args[0] & 0x04 ? 1 : 0) : state.int_latched,
      },
    }),
    tile_sense_i_6p6_int1_data_ready: ({ state, args }) => ({
      nextState: { int1_drdy: pick(args, 0, state.int1_drdy) },
    }),
    tile_sense_i_6p6_int1_fifo_ths: ({ state, args }) => ({
      nextState: { int1_fifo: pick(args, 0, state.int1_fifo) },
    }),
    tile_sense_i_6p6_int1_wom: ({ state, args }) => ({
      nextState: { int1_wom: pick(args, 0, state.int1_wom) },
    }),
    tile_sense_i_6p6_int2_data_ready: ({ state, args }) => ({
      nextState: { int2_drdy: pick(args, 0, state.int2_drdy) },
    }),
    tile_sense_i_6p6_int2_fifo_ths: ({ state, args }) => ({
      nextState: { int2_fifo: pick(args, 0, state.int2_fifo) },
    }),
    tile_sense_i_6p6_int2_wom: ({ state, args }) => ({
      nextState: { int2_wom: pick(args, 0, state.int2_wom) },
    }),
    tile_sense_i_6p6_set_int_pulse_duration: ({ args }) => ({
      nextState: { _int_pulse: pick(args, 0, 0) },
    }),
    tile_sense_i_6p6_get_int_status: ({ state }) => ({ scalar: intStatus(state) }),
    tile_sense_i_6p6_get_int_status2: ({ state }) => ({ scalar: womActive(state) ? 0x07 : 0 }),
    tile_sense_i_6p6_get_int_status3: ({ state }) => ({ scalar: tiltActive(state) ? 0x08 : 0 }),

    // ── wake-on-motion ──
    tile_sense_i_6p6_wom_config: ({ state, args }) => ({
      nextState: { wom_thr_mg: pick(args, 0, state.wom_thr_mg) },
    }),
    tile_sense_i_6p6_wom_enable: () => ({ nextState: { wom_enabled: 1 } }),
    tile_sense_i_6p6_wom_disable: () => ({ nextState: { wom_enabled: 0 } }),
    tile_sense_i_6p6_smd_config: ({ args }) => ({ nextState: { _smd: pick(args, 0, 0) } }),

    // ── APEX: pedometer ──
    tile_sense_i_6p6_pedometer_enable: () => ({ nextState: { ped_enabled: 1 } }),
    tile_sense_i_6p6_pedometer_disable: () => ({ nextState: { ped_enabled: 0 } }),
    tile_sense_i_6p6_get_step_count: ({ state }) => ({ scalar: state.step_count }),
    tile_sense_i_6p6_get_step_cadence: ({ state }) => ({ scalar: state.step_cadence }),
    tile_sense_i_6p6_get_activity: ({ state }) => ({
      scalar: state.ped_enabled && state.step_cadence > 0 ? 1 : 0,
    }),

    // ── APEX: tilt ──
    tile_sense_i_6p6_tilt_enable: () => ({ nextState: { tilt_enabled: 1 } }),
    tile_sense_i_6p6_tilt_disable: () => ({ nextState: { tilt_enabled: 0 } }),

    // ── APEX: tap ──
    tile_sense_i_6p6_tap_enable: () => ({ nextState: { tap_enabled: 1 } }),
    tile_sense_i_6p6_tap_disable: () => ({ nextState: { tap_enabled: 0 } }),
    tile_sense_i_6p6_get_tap_result: () => ({ array: [0, 0, 0] }),
    tile_sense_i_6p6_get_tap_result_flat: () => ({ scalar: 0 }),

    // ── FIFO ──
    tile_sense_i_6p6_fifo_config: ({ state, args }) => ({
      nextState: { fifo_mode: pick(args, 0, state.fifo_mode) },
    }),
    tile_sense_i_6p6_fifo_set_watermark: ({ state, args }) => ({
      nextState: { fifo_watermark: Math.max(1, pick(args, 0, state.fifo_watermark)) },
    }),
    tile_sense_i_6p6_fifo_flush: () => ({ nextState: { fifo_count: 0 } }),
    tile_sense_i_6p6_fifo_count: ({ state }) => ({ scalar: state.fifo_count }),
    tile_sense_i_6p6_fifo_lost_count: ({ state }) => ({ scalar: state.fifo_lost }),
    tile_sense_i_6p6_fifo_read_packet: ({ state }) => ({
      array: [
        rawAccel(state.ax_mg, state.accel_range),
        rawAccel(state.ay_mg, state.accel_range),
        rawAccel(state.az_mg, state.accel_range),
        rawGyro(state.gx_dps, state.gyro_range),
        rawGyro(state.gy_dps, state.gyro_range),
        rawGyro(state.gz_dps, state.gyro_range),
      ],
    }),
    tile_sense_i_6p6_fifo_read_packet_flat: ({ state }) => ({
      array: [
        rawAccel(state.ax_mg, state.accel_range),
        rawAccel(state.ay_mg, state.accel_range),
        rawAccel(state.az_mg, state.accel_range),
      ],
    }),
    tile_sense_i_6p6_fifo_read_packets: ({ state }) => ({ scalar: state.fifo_count }),
    tile_sense_i_6p6_fifo_read_packets_flat: ({ state }) => ({ scalar: state.fifo_count }),

    // ── advanced ──
    tile_sense_i_6p6_set_gyro_offset: ({ args }) => ({ nextState: { _goff: pick(args, 0, 0) } }),
    tile_sense_i_6p6_set_accel_offset: ({ args }) => ({ nextState: { _aoff: pick(args, 0, 0) } }),
    tile_sense_i_6p6_self_test: () => ({ scalar: 1 }),
    tile_sense_i_6p6_read_reg: ({ args }) => ({ scalar: pick(args, 0, 0) === 0x75 ? WHO_AM_I : 0 }),
    tile_sense_i_6p6_write_reg: ({ args }) => ({ nextState: { _last_reg: pick(args, 1, 0) } }),
  },

  // Provenance per host call (unlisted ⇒ "inferred"). Canonical = the number,
  // bit layout, or formula is verified against the ICM-42686P datasheet;
  // hallucinated = a placeholder whose behavior isn't really modeled yet.
  provenance: {
    // canonical — datasheet conversions / register bits
    tile_sense_i_6p6_find: 'canonical', // I2C addr 0x69
    tile_sense_i_6p6_get_raw_accels: 'canonical', // LSB/g table
    tile_sense_i_6p6_get_raw_gyros: 'canonical', // LSB/dps table
    tile_sense_i_6p6_get_raw_6dof: 'canonical',
    tile_sense_i_6p6_get_raw_all: 'canonical',
    tile_sense_i_6p6_get_temperature: 'canonical', // raw/132.48 + 25
    tile_sense_i_6p6_set_accel_range: 'canonical', // ACCEL_FS_SEL
    tile_sense_i_6p6_set_gyro_range: 'canonical', // GYRO_FS_SEL
    tile_sense_i_6p6_set_power_mode: 'canonical', // PWR_MGMT0
    tile_sense_i_6p6_data_ready: 'canonical',
    tile_sense_i_6p6_get_int_status: 'canonical', // INT_STATUS bits
    tile_sense_i_6p6_get_int_status2: 'canonical', // WOM bits
    tile_sense_i_6p6_get_int_status3: 'canonical', // tilt/tap bits
    tile_sense_i_6p6_int1_data_ready: 'canonical', // INT_SOURCE0
    tile_sense_i_6p6_int1_fifo_ths: 'canonical',
    tile_sense_i_6p6_int1_wom: 'canonical', // INT_SOURCE1
    tile_sense_i_6p6_int2_data_ready: 'canonical', // INT_SOURCE3
    tile_sense_i_6p6_int2_fifo_ths: 'canonical',
    tile_sense_i_6p6_int2_wom: 'canonical', // INT_SOURCE4
    tile_sense_i_6p6_wom_config: 'canonical', // thr = mg*256/1000

    // hallucinated — placeholders not truly modeled
    tile_sense_i_6p6_get_tap_result: 'hallucinated',
    tile_sense_i_6p6_get_tap_result_flat: 'hallucinated',
    tile_sense_i_6p6_wait_for_tap: 'hallucinated',
    tile_sense_i_6p6_fifo_read_packets: 'hallucinated',
    tile_sense_i_6p6_fifo_read_packets_flat: 'hallucinated',
    tile_sense_i_6p6_set_filter_bw: 'hallucinated',
    tile_sense_i_6p6_set_filter_order: 'hallucinated',
    tile_sense_i_6p6_set_temp_filter: 'hallucinated',
    tile_sense_i_6p6_set_gyro_offset: 'hallucinated',
    tile_sense_i_6p6_set_accel_offset: 'hallucinated',
    tile_sense_i_6p6_smd_config: 'hallucinated',
    tile_sense_i_6p6_write_reg: 'hallucinated',
    tile_sense_i_6p6_self_test: 'hallucinated',
    power: 'canonical', // ICM-42686P Table 3 D.C. characteristics (LP figure estimated)
  },

  // Time-evolution: FIFO fills while enabled; the pedometer counts steps while
  // the device is moving.
  deriveState(state) {
    const patch: Partial<State> = {};
    if (state.fifo_mode !== 0 && sensorsOn(state)) {
      patch.fifo_count = Math.min(4095, state.fifo_count + 1);
    }
    if (state.ped_enabled === 1 && motionMg(state) > 50) {
      patch.step_count = state.step_count + 1;
      patch.step_cadence = 8; // 2 steps/s in u6.2
    } else if (state.ped_enabled === 1) {
      patch.step_cadence = 0;
    }
    return patch;
  },

  // INT pin drive levels. Each pin ORs its routed sources; APEX tilt routes to
  // INT1 by default. Active-low inverts the level.
  padOutputs(state) {
    const drdy = dataReady(state) === 1;
    const fifo = fifoThsActive(state);
    const wom = womActive(state);
    const tilt = tiltActive(state);

    let int1 =
      (state.int1_drdy === 1 && drdy) ||
      (state.int1_fifo === 1 && fifo) ||
      (state.int1_wom === 1 && wom) ||
      tilt;
    let int2 =
      (state.int2_drdy === 1 && drdy) ||
      (state.int2_fifo === 1 && fifo) ||
      (state.int2_wom === 1 && wom);

    if (state.int_active_high === 0) {
      int1 = !int1;
      int2 = !int2;
    }
    return { INT1: int1 ? 1 : 0, INT2: int2 ? 1 : 0 };
  },

  // Single 1.8 V supply. Current by power mode (ICM-42686P datasheet typicals):
  // sleep 7.5 µA, accel-only LN 0.28 mA, gyro-only LN 0.58 mA, both LN 0.70 mA.
  power(state) {
    const accelLN = state.accel_pm === 3;
    const accelLP = state.accel_pm === 2;
    const gyroLN = state.gyro_pm === 3;
    let ua = 7.5; // sleep
    if (gyroLN && (accelLN || accelLP)) ua = 700;
    else if (gyroLN) ua = 580;
    else if (accelLN) ua = 280;
    else if (accelLP) ua = 20; // LP not in datasheet — estimate
    return {
      draw_ua: ua,
      rails: [{ name: 'V+', role: 'supply', v_mv: 1800, i_ua: ua, pads: ['10'] }],
    };
  },
};

export default sim;
